SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('不要在这种时候才想起我','不谐之音','不赴','与你重逢','专属巧克力味觉','世末创作者','世界末日 - armgeddon','世界沉睡童话nirvana xs洛ver','世界沉睡童话nirvana 艾尔法ver','世界沉睡童话nirvana 雨狸ver','临川浮梦','主板都市(feat.语飞）','乡愁','云梦醉雨','人造树的幽灵 - ghosts of artificial trees','他','依然和你在一起','俯首望槐安(feat.宙暮,罗思贤,君凝华)','借电波相拥','假想敌','健忘症','光梦交响','光的阴影','兑上阙','全息投影的脈動','写给社交恐惧症的一首歌','冬已去,春未来。','冬止め','决心','凤凰社印象曲','北洋','十七号列车','十字街口','千年雪','午前零时') ORDER BY sm.title,sm.album_id